import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {spawnSync} from 'node:child_process';
import {createManifest, verifyManifest} from '../snapshot.js';

const script = fileURLToPath(new URL('../snapshot.js', import.meta.url));
function fixture(t) {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'snapshot-extra-'));
  t.after(() => fs.rmSync(root, {recursive:true, force:true}));
  return root;
}
function put(root, name, bytes = 'abc') {
  const target = path.join(root, name);
  fs.mkdirSync(path.dirname(target), {recursive:true});
  fs.writeFileSync(target, bytes);
  fs.chmodSync(target, 0o640);
}
function cli(args, status) {
  const result = spawnSync(process.execPath, [script, ...args], {encoding:'utf8'});
  assert.ifError(result.error);
  assert.equal(result.status, status, result.stderr);
  if (status === 2) {
    assert.equal(result.stdout, '');
    assert.ok(result.stderr.trim());
    return;
  }
  assert.equal(result.stderr, '');
  const value = JSON.parse(result.stdout);
  assert.equal(result.stdout, JSON.stringify(value) + '\n');
  return value;
}

test('sorted, immutable manifests and all drift categories', t => {
  const root = fixture(t);
  const names = ['é', 'Z', ' space\t\n', 'both', 'content', 'mode', 'gone/a', 'gone/b', 'link/a', 'blocked/a', 'dir', 'dangling'];
  names.forEach(name => put(root, name, Buffer.from([0, 255, 10])));
  const selections = Object.freeze([...names]);
  const manifest = createManifest(root, selections);
  assert.deepEqual(manifest.files.map(e => e.path), [...names].sort());
  const input = Object.freeze({version:1, extra:true, files:Object.freeze([...manifest.files].reverse().map(e => Object.freeze({...e, extra:true})))});
  assert.deepEqual(verifyManifest(root, input), {ok:true, unchanged:[...names].sort(), changed:[], missing:[], unsafe:[]});
  put(root, 'both', 'different'); fs.chmodSync(path.join(root, 'both'), 0o600);
  put(root, 'content', 'xyz');
  fs.chmodSync(path.join(root, 'mode'), 0o600);
  fs.rmSync(path.join(root, 'gone'), {recursive:true});
  fs.rmSync(path.join(root, 'link'), {recursive:true});
  fs.symlinkSync(root, path.join(root, 'link'));
  fs.rmSync(path.join(root, 'blocked'), {recursive:true}); put(root, 'blocked');
  fs.unlinkSync(path.join(root, 'dir')); fs.mkdirSync(path.join(root, 'dir'));
  fs.unlinkSync(path.join(root, 'dangling')); fs.symlinkSync('absent', path.join(root, 'dangling'));
  assert.deepEqual(verifyManifest(root, input), {
    ok:false, unchanged:['é', 'Z', ' space\t\n'].sort(),
    changed:[{path:'both', reasons:['content', 'mode']}, {path:'content', reasons:['content']}, {path:'mode', reasons:['mode']}],
    missing:['gone/a', 'gone/b'], unsafe:['blocked/a', 'dangling', 'dir', 'link/a'],
  });
  for (const name of ['gone/a', 'link/a', 'blocked/a', 'dir', 'dangling']) {
    assert.throws(() => createManifest(root, [name]), Error);
  }
  assert.deepEqual(selections, names);
  assert.deepEqual(fs.readFileSync(path.join(root, 'Z')), Buffer.from([0, 255, 10]));
});

test('complete validation, canonical paths and numeric boundaries', t => {
  const root = fixture(t); put(root, 'a');
  const manifest = createManifest(root, ['a']);
  const entry = manifest.files[0];
  for (const invalid of [null, [], {}, {version:2, files:[]}, {version:1, files:null}, {version:1, files:[null]}, {version:1, files:[[]]}, {version:1, files:[entry, entry]}]) {
    assert.throws(() => verifyManifest(root, invalid), Error);
  }
  for (const invalid of ['', '/a', 'a\\b', 'a\0b', 'a//b', './a', 'a/.', '../a', 'a/../b', 'a/', 1, null]) {
    assert.throws(() => createManifest(root, [invalid]), Error);
    assert.throws(() => verifyManifest(root, {version:1, files:[{...entry, path:invalid}]}), Error);
  }
  assert.throws(() => createManifest(root, ['a', 'a']), Error);
  assert.throws(() => createManifest(root, 'a'), Error);
  for (const [key, values] of Object.entries({
    sha256:['A'.repeat(64), 'a'.repeat(63), 'a'.repeat(64) + '\n', 123, null],
    size:[-1, 0.5, NaN, Infinity, Number.MAX_SAFE_INTEGER + 1, '3', null],
    mode:[-1, 512, 0.5, NaN, Infinity, '420', null],
  })) {
    for (const value of values) assert.throws(() => verifyManifest(root, {version:1, files:[{...entry, [key]:value}]}), Error);
  }
  for (const size of [0, Number.MAX_SAFE_INTEGER]) {
    assert.deepEqual(verifyManifest(root, {version:1, files:[{...entry, size}]}).changed, [{path:'a', reasons:['content']}]);
  }
  for (const mode of [0, 511]) {
    assert.deepEqual(verifyManifest(root, {version:1, files:[{...entry, mode}]}).changed, [{path:'a', reasons:['mode']}]);
  }
  for (const key of ['path', 'sha256', 'size', 'mode']) {
    const incomplete = {...entry}; delete incomplete[key];
    assert.throws(() => verifyManifest(root, {version:1, files:[incomplete]}), Error);
  }
  assert.deepEqual(createManifest(root, []), {version:1, files:[]});
  assert.equal(verifyManifest(root, {version:1, files:[]}).ok, true);
});

test('invalid roots including symlinks with trailing slash', t => {
  const base = fixture(t); fs.mkdirSync(path.join(base, 'root')); put(base, 'file');
  fs.symlinkSync('root', path.join(base, 'alias'));
  for (const root of ['missing', 'file', 'alias', 'alias/'].map(p => path.join(base, p) + (p.endsWith('/') ? '/' : ''))) {
    assert.throws(() => createManifest(root, []), Error);
    assert.throws(() => verifyManifest(root, {version:1, files:[]}), Error);
  }
});

test('CLI exit codes and exact output on success and errors; import is quiet', t => {
  const root = fixture(t); put(root, 'a');
  const manifest = cli(['create', root, 'a'], 0);
  assert.deepEqual(manifest, createManifest(root, ['a']));
  assert.deepEqual(cli(['create', root], 0), {version:1, files:[]});
  const input = path.join(root, 'manifest.json');
  fs.writeFileSync(input, JSON.stringify(manifest));
  assert.deepEqual(cli(['verify', root, input], 0), verifyManifest(root, manifest));
  put(root, 'a', 'changed');
  assert.deepEqual(cli(['verify', root, input], 1), verifyManifest(root, manifest));
  for (const args of [[], ['other'], ['create'], ['verify'], ['verify', root], ['verify', root, input, 'extra'], ['create', root, '../bad'], ['create', root, 'absent'], ['create', root, 'a', 'a'], ['create', input], ['verify', root, root], ['verify', root, input + '.absent'], ['verify', input, input]]) cli(args, 2);
  fs.writeFileSync(input, '{'); cli(['verify', root, input], 2);
  fs.writeFileSync(input, '{"version":2,"files":[]}'); cli(['verify', root, input], 2);
  const imported = spawnSync(process.execPath, ['--input-type=module', '-e', `import ${JSON.stringify(new URL('../snapshot.js', import.meta.url).href)}`], {encoding:'utf8'});
  assert.ifError(imported.error);
  assert.equal(imported.status, 0);
  assert.equal(imported.stdout, ''); assert.equal(imported.stderr, '');
});

